exercises.solutionCode:
typedef enum {
    WDG_FEED_INVALID   = -1,
    WDG_FEED_OK        = 0,
    WDG_FEED_TOO_EARLY = 1,
    WDG_FEED_TOO_LATE  = 2
} WdgFeedResult;

WdgFeedResult wdg_feed_check(unsigned int elapsed_ms,
                             unsigned int window_low_ms,
                             unsigned int window_high_ms)
{
    /* 窗口区间本身必须合法：下限不能为 0，且不能大于上限 */
    if (window_low_ms == 0u || window_low_ms > window_high_ms) {
        return WDG_FEED_INVALID;
    }

    if (elapsed_ms < window_low_ms) {
        return WDG_FEED_TOO_EARLY;
    }
    if (elapsed_ms > window_high_ms) {
        return WDG_FEED_TOO_LATE;
    }

    return WDG_FEED_OK;
}
